:root {
  --bg: #1b1f2a;
  --surface: #2a3040;
  --surface-2: #353d52;
  --accent: #f2c14e;
  --text: #f5f7fa;
  --muted: #aab3c5;
  --card-back: #4a5570;
  --card-back-hover: #5a6685;
  --match: #3ecf8e;
  --radius: 12px;
  --gap: 12px;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(circle at top, #2a3040 0%, var(--bg) 70%);
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  padding: 24px 16px;
}

.game {
  width: 100%;
  max-width: 520px;
  background: var(--surface);
  border-radius: 20px;
  padding: 24px;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.45);
}

.game-header h1 {
  margin: 0 0 4px;
  font-size: 1.6rem;
  letter-spacing: 0.5px;
}

.subtitle {
  margin: 0;
  color: var(--muted);
  font-size: 1rem;
}

.status-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin: 20px 0 16px;
  min-height: 32px;
}

.moves {
  margin: 0;
  font-weight: 600;
  font-size: 1.05rem;
}

.message {
  margin: 0;
  color: var(--accent);
  font-weight: 600;
  text-align: right;
}

.board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--gap);
}

.card {
  position: relative;
  aspect-ratio: 1 / 1;
  border: none;
  border-radius: var(--radius);
  background: var(--card-back);
  cursor: pointer;
  padding: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.4rem;
  color: transparent;
  transition: transform 0.15s ease, background 0.2s ease, box-shadow 0.2s ease;
  box-shadow: inset 0 0 0 2px rgba(255, 255, 255, 0.06);
}

.card::before {
  content: "?";
  color: rgba(255, 255, 255, 0.55);
  font-weight: 700;
  font-size: 1.5rem;
}

.card:hover:not(.matched):not([aria-disabled="true"]) {
  background: var(--card-back-hover);
  transform: translateY(-2px);
}

.card:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.card:active:not(.matched):not([aria-disabled="true"]) {
  transform: translateY(0);
}

.card.flipped,
.card.matched {
  background: var(--color, var(--surface-2));
  box-shadow: inset 0 0 0 2px rgba(255, 255, 255, 0.18);
}

.card.flipped::before,
.card.matched::before {
  content: "";
}

.card.matched {
  cursor: default;
  box-shadow: 0 0 0 3px var(--match), inset 0 0 0 2px rgba(255, 255, 255, 0.25);
}

.card[aria-disabled="true"] {
  cursor: default;
}

.controls {
  margin-top: 20px;
  display: flex;
  justify-content: center;
}

.btn {
  font: inherit;
  font-weight: 600;
  font-size: 1.05rem;
  color: #1b1f2a;
  background: var(--accent);
  border: none;
  border-radius: 10px;
  padding: 12px 28px;
  cursor: pointer;
  transition: transform 0.12s ease, background 0.2s ease, box-shadow 0.2s ease;
  box-shadow: 0 4px 0 #b8933a;
}

.btn:hover {
  background: #ffd166;
}

.btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 3px;
}

.btn:active {
  transform: translateY(3px);
  box-shadow: 0 1px 0 #b8933a;
}

@media (max-width: 420px) {
  body {
    padding: 16px 10px;
  }
  .game {
    padding: 18px;
  }
  :root {
    --gap: 8px;
  }
  .game-header h1 {
    font-size: 1.35rem;
  }
  .status-bar {
    flex-direction: column;
    align-items: flex-start;
    gap: 4px;
  }
  .message {
    text-align: left;
  }
}

(function () {
  'use strict';

  var COLORS = [
    '#e63946', '#f4a261', '#e9c46a', '#2a9d8f',
    '#4d96ff', '#9b5de5', '#ff6fb5', '#6c757d'
  ];

  var board = document.getElementById('board');
  var moveCountEl = document.getElementById('moveCount');
  var messageEl = document.getElementById('message');
  var newGameBtn = document.getElementById('newGame');

  var state = {
    deck: [],
    flipped: [],
    matched: 0,
    moves: 0,
    lock: false
  };

  function shuffle(arr) {
    for (var i = arr.length - 1; i > 0; i--) {
      var j = Math.floor(Math.random() * (i + 1));
      var tmp = arr[i];
      arr[i] = arr[j];
      arr[j] = tmp;
    }
    return arr;
  }

  function buildDeck() {
    var deck = [];
    COLORS.forEach(function (color, index) {
      deck.push({ id: index + '-' + Math.random(), color: color, pair: index });
      deck.push({ id: index + '-' + Math.random(), color: color, pair: index });
    });
    return shuffle(deck);
  }

  function render() {
    board.innerHTML = '';
    state.deck.forEach(function (card) {
      var btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'card';
      btn.setAttribute('role', 'gridcell');
      btn.setAttribute('aria-label', 'Face-down card');
      btn.dataset.pair = card.pair;
      btn.dataset.id = card.id;
      btn.style.setProperty('--color', card.color);
      btn.addEventListener('click', onCardClick);
      board.appendChild(btn);
    });
  }

  function onCardClick(event) {
    var card = event.currentTarget;
    if (state.lock) return;
    if (card.classList.contains('flipped') || card.classList.contains('matched')) return;

    flipCard(card);
    state.flipped.push(card);

    if (state.flipped.length === 2) {
      state.moves++;
      moveCountEl.textContent = state.moves;
      checkMatch();
    }
  }

  function flipCard(card) {
    card.classList.add('flipped');
    card.setAttribute('aria-label', 'Revealed card');
  }

  function checkMatch() {
    var first = state.flipped[0];
    var second = state.flipped[1];
    state.lock = true;

    if (first.dataset.pair === second.dataset.pair) {
      first.classList.add('matched');
      second.classList.add('matched');
      first.setAttribute('aria-disabled', 'true');
      second.setAttribute('aria-disabled', 'true');
      first.setAttribute('aria-label', 'Matched card');
      second.setAttribute('aria-label', 'Matched card');
      state.matched++;
      state.flipped = [];
      state.lock = false;
      if (state.matched === COLORS.length) {
        messageEl.textContent = 'You win! All pairs matched in ' + state.moves + ' moves.';
      }
    } else {
      setTimeout(function () {
        first.classList.remove('flipped');
        second.classList.remove('flipped');
        first.setAttribute('aria-label', 'Face-down card');
        second.setAttribute('aria-label', 'Face-down card');
        state.flipped = [];
        state.lock = false;
      }, 700);
    }
  }

  function newGame() {
    state.deck = buildDeck();
    state.flipped = [];
    state.matched = 0;
    state.moves = 0;
    state.lock = false;
    moveCountEl.textContent = '0';
    messageEl.textContent = '';
    render();
    var firstCard = board.querySelector('.card');
    if (firstCard) firstCard.focus();
  }

  newGameBtn.addEventListener('click', newGame);

  newGame();
})();
